window.addEventListener('unhandledrejection',e=>{console.error(e.reason);toast(e.reason?.message||'An operation could not be completed.','error');});
function request(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('ThirdRailify-Notespace-POC',1);r.onupgradeneeded=()=>{r.result.createObjectStore('boards',{keyPath:'id'});r.result.createObjectStore('assets',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function dbGet(store,id){return request(state.db.transaction(store).objectStore(store).get(id));}
