async function dbPut(store,value){return new Promise((resolve,reject)=>{const tx=state.db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
async function dbDelete(store,id){return new Promise((resolve,reject)=>{const tx=state.db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function patchDB(id,change){return new Promise((resolve,reject)=>{const tx=state.db.transaction('boards','readwrite'),s=tx.objectStore('boards'),r=s.get(id);let merged;r.onsuccess=()=>{if(!r.result){tx.abort();return;}merged=M.apply(r.result,change);s.put(merged);};tx.oncomplete=()=>resolve(merged);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(Error('This board no longer exists. Export your current work before closing it.'));});}
let channel=null;try{channel=new BroadcastChannel('thirdrailify-notespace-local-v1');}catch{}
function broadcast(msg){channel?.postMessage({...msg,peerId:state.peerId,boardId:state.board?.id,name:state.identity,at:Date.now()});}
