 if(n.type==='note')html=top+`<div class="note-body"><div class="note-title">${esc(n.title)}</div><div class="note-copy">${esc(n.text)}</div></div>`+footer;
 if(n.type==='text')html=`${n.tags.includes('starter')?'<div class="text-overline">THE OPEN NOTEBOOK / STARTER BOARD</div>':''}<div class="text-title" style="font-size:${n.fontSize||44}px">${esc(n.title)}</div><div class="text-subtitle">${esc(n.text)}</div>`;
 if(n.type==='frame'){const children=state.board.objects.filter(x=>x.parentId===n.id);html=`<div class="frame-head">${icon('frame')}<span>${esc(n.title)}</span><span class="frame-count">${children.length}</span></div><div class="children">${children.map(renderNode).join('')}</div>`;}
 if(n.type==='checklist'){const list=n.items||[],done=list.filter(i=>i.done).length;html=`<div class="checklist-title">${esc(n.title)}</div><div class="checklist-sub">${esc(n.text||`${done} of ${list.length} complete`)}</div><div class="task-progress"><span style="width:${list.length?done/list.length*100:0}%"></span></div><div class="task-rows">${list.map(i=>`<div class="task-row"><button class="task-check ${i.done?'done':''}" data-action="check-task" data-node="${n.id}" data-task="${i.id}" aria-label="${i.done?'Reopen':'Complete'} ${attr(i.text)}" aria-pressed="${i.done}">${i.done?icon('check'):''}</button><div class="task-info ${i.done?'done':''}"><span>${esc(i.text)}</span><small>${esc(i.owner||'Unassigned')}${i.due?' · '+esc(i.due):''}</small></div></div>`).join('')}<button class="task-add" data-action="edit-node" data-node="${n.id}">+ Add / edit items</button></div>`;}
 if(n.type==='media'){const src=mediaSrc(n),isGif=n.mime==='image/gif'||n.provider;html=`<div class="media-wrap">${src?`<img src="${attr(src)}" alt="${attr(n.title||n.fileName||'Board media')}" draggable="false" style="object-fit:${n.fit==='cover'?'cover':'contain'}">`:`<div class="media-overlay">${icon('image')}<span>${n.provider?'Provider reference · click to load':'Image unavailable on this device'}</span>${n.provider?`<button data-action="resolve-gif" data-node="${n.id}">Load ${n.provider==='giphy'?'GIPHY':'Tenor'} GIF</button>`:''}</div>`}</div><div class="media-caption"><span>${esc(n.title||n.fileName||'Image')}</span><small>${isGif?'GIF':esc((n.mime||'image').split('/')[1]?.toUpperCase()||'IMAGE')}</small></div>`;}
