function pathFromPoints(pts){return(pts||[]).map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');}
function edgeEnds(e){const map=M.index(state.board);let a=e.from.nodeId?map.get(e.from.nodeId):null,b=e.to.nodeId?map.get(e.to.nodeId):null;const ap=a?M.worldPosition(a,map):e.from,bp=b?M.worldPosition(b,map):e.to;let p=a?{x:ap.x+a.w/2,y:ap.y+a.h/2}:{...ap},q=b?{x:bp.x+b.w/2,y:bp.y+b.h/2}:{...bp};const ac={...p},bc={...q};const side=(node,origin,c,other)=>{const dx=other.x-c.x,dy=other.y-c.y;if(Math.abs(dx)/node.w>Math.abs(dy)/node.h)return{x:dx>=0?origin.x+node.w:origin.x,y:c.y};return{x:c.x,y:dy>=0?origin.y+node.h:origin.y};};if(a)p=side(a,ap,ac,bc);if(b)q=side(b,bp,bc,ac);return{p,q};}
function renderEdges(){if(!state.board)return;let html=`<defs><marker id="arrow-head" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1 9 5 1 9" fill="none" stroke="#b5a0cb" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></marker></defs>`;
 for(const e of state.board.edges){const{p,q}=edgeEnds(e);let d;if(e.style==='straight')d=`M${p.x} ${p.y}L${q.x} ${q.y}`;else if(e.style==='elbow')d=`M${p.x} ${p.y}H${(p.x+q.x)/2}V${q.y}H${q.x}`;else{const bend=Math.max(35,Math.abs(q.x-p.x)*.45);d=`M${p.x} ${p.y}C${p.x+bend} ${p.y},${q.x-bend} ${q.y},${q.x} ${q.y}`;}html+=`<g><path data-edge="${attr(e.id)}" class="edge-line hit" d="${d}" fill="none"/><path class="edge-line" data-edge="${attr(e.id)}" d="${d}" fill="none" stroke="${e.id===state.edgeId?'#edc767':M.color(e.color)}" stroke-width="${e.id===state.edgeId?3:1.8}" ${e.arrow?'marker-end="url(#arrow-head)"':''}/>${e.label?`<text x="${(p.x+q.x)/2}" y="${(p.y+q.y)/2-13}" text-anchor="middle" class="edge-label">${esc(e.label)}</text>`:''}</g>`;}
 if(state.connector?.preview){const p=state.connector.start.nodeId?edgeEnds({from:state.connector.start,to:state.connector.preview}).p:state.connector.start;html+=`<path d="M${p.x} ${p.y} L${state.connector.preview.x} ${state.connector.preview.y}" fill="none" stroke="#ebc76b" stroke-dasharray="5 5" stroke-width="2"/>`;}
 $('#edges').innerHTML=html;
}
function applyCamera(){const {x,y,z}=state.camera;$('#world').style.transform=`translate(${x}px,${y}px) scale(${z})`;$('#zoom-value').textContent=Math.round(z*100)+'%';const pat=$('#canvas-pattern');pat.style.backgroundPosition=`${x}px ${y}px`;pat.style.backgroundSize=`${24*z}px ${24*z}px`;renderCursors();}
function fitBoard(ids=null){if(!state.board)return;const r=$('#viewport').getBoundingClientRect(),b=M.bounds(state.board,ids);const p=innerWidth<620?26:48,top=98,bottom=112;const z=Math.max(.15,Math.min(1.15,Math.min((r.width-p*2)/b.w,(r.height-top-bottom)/b.h)));state.camera={x:(r.width-b.w*z)/2-b.x*z,y:top+(r.height-top-bottom-b.h*z)/2-b.y*z,z};applyCamera();renderMinimap();}
function zoom(f,point=null){const r=$('#viewport').getBoundingClientRect(),p=point||{x:r.width/2,y:r.height/2},old=state.camera.z,z=Math.max(.15,Math.min(3,old*f));state.camera.x=p.x-(p.x-state.camera.x)*z/old;state.camera.y=p.y-(p.y-state.camera.y)*z/old;state.camera.z=z;applyCamera();}
function renderMinimap(){const b=M.bounds(state.board),map=M.index(state.board),s=Math.min(140/b.w,75/b.h),ox=(150-b.w*s)/2,oy=(85-b.h*s)/2;$('#minimap').innerHTML=state.board.objects.map(n=>{const p=M.worldPosition(n,map);return `<rect x="${ox+(p.x-b.x)*s}" y="${oy+(p.y-b.y)*s}" width="${Math.max(2,n.w*s)}" height="${Math.max(2,n.h*s)}" rx="1" fill="${n.type==='frame'?'#2b2631':M.color(n.tint)}" fill-opacity="${n.type==='frame'?'.5':'.55'}" stroke="${n.type==='frame'?'#665473':'none'}" stroke-width=".7"/>`;}).join('');}
async function background(){const seq=++state.bgSequence,bg=state.board.background;const el=$('#canvas-background');el.style.backgroundColor=bg.color;el.style.backgroundImage=bg.mode==='gradient'?`linear-gradient(${bg.angle}deg,${bg.color},${bg.gradientEnd})`:'none';if(bg.mode==='image'&&bg.imageId){await hydrate();if(seq!==state.bgSequence)return;const src=state.urls.get(bg.imageId);if(src)el.style.backgroundImage=`linear-gradient(#131415${Math.round((1-bg.opacity)*255).toString(16).padStart(2,'0')},#131415${Math.round((1-bg.opacity)*255).toString(16).padStart(2,'0')}),url("${src}")`;}
 const patterns={dots:'radial-gradient(#85868d55 1px,transparent 1px)',grid:'linear-gradient(#85868d18 1px,transparent 1px),linear-gradient(90deg,#85868d18 1px,transparent 1px)',lines:'repeating-linear-gradient(135deg,transparent 0 23px,#85868d1c 23px 24px)',none:'none'};$('#canvas-pattern').style.backgroundImage=patterns[bg.pattern];}
