function selectedNode(){return state.board?.objects.find(n=>state.selected.has(n.id));}
function renderSelectionToolbar(){const el=$('#selection-toolbar');const count=state.selected.size+(state.edgeId?1:0);el.hidden=!count;if(!count)return;const n=selectedNode();el.innerHTML=`<span class="label">${count} SELECTED</span>${!state.edgeId?button('edit-selected','edit','Edit content')+button('duplicate','copy','Duplicate · Ctrl D')+button('group','group','Group in container')+(n?.type==='frame'?button('ungroup','ungroup','Ungroup container'):'')+button('lock-selected',n?.locked?'unlock':'lock',n?.locked?'Unlock':'Lock')+button('bring-front','up','Bring to front'):''}${button('delete-selected','trash','Delete selection')}`;}
