 if(edge){el.innerHTML=`<div class="object-type-badge">${icon('arrow')} ATTACHED / FREE LEADER</div>${field('Label',`<input data-edge-field="label" value="${attr(edge.label)}">`)}${field('Line style',`<select data-edge-field="style">${['curve','straight','elbow'].map(s=>`<option ${edge.style===s?'selected':''}>${s}</option>`).join('')}</select>`)}${field('Color',`<input type="color" data-edge-field="color" value="${M.color(edge.color)}">`)}<label class="switch-line"><input type="checkbox" data-edge-field="arrow" ${edge.arrow?'checked':''}>Arrowhead</label><div class="helper-card">Connected ends follow their objects, including objects inside containers. Free ends keep their canvas position.</div>`;return;}
 if(state.selected.size>1){el.innerHTML=`<div class="helper-card"><strong>${state.selected.size} objects selected</strong>Drag any selected object to move the set. Group them into a container to keep them together.</div><div class="inspector-section">${swatches()}</div><div class="layer-buttons spaced"><button class="secondary-button" data-action="group">${icon('group')} Group</button><button class="secondary-button" data-action="duplicate">${icon('copy')} Duplicate</button></div><button class="danger-button full spaced" data-action="delete-selected">${icon('trash')} Delete selected</button>`;return;}
 if(!n){const tasks=state.board.objects.flatMap(n=>n.items||[]),done=tasks.filter(t=>t.done).length;el.innerHTML=`<div class="helper-card">${icon('spark')}<strong>A space for your next idea.</strong>Select anything to edit its content, tags, assignment and structured fields.</div><div class="stats-grid spaced"><div class="stat-box"><strong>${state.board.objects.length}</strong><span>Objects on canvas</span></div><div class="stat-box"><strong>${done}/${tasks.length}</strong><span>Tasks complete</span></div></div><div class="section-heading"><strong>Canvas surface</strong><span class="mini-tag">5% SAT</span></div><div class="swatches">${['#131415','#17141b','#191814','#f1efe9'].map(c=>`<button class="swatch large" style="--swatch:${c}" data-action="bg-quick" data-color="${c}" title="${c}" aria-label="Canvas color ${c}"></button>`).join('')}</div><button class="quiet-button full spaced" data-action="appearance">${icon('palette')} Background & patterns</button><div class="inspector-section"><div class="section-heading"><strong>Build your board</strong></div><p class="compact-info">Double-click a card to edit. Drag it anywhere. Drop an object into a container to parent it. Shift-click for multiple selection.</p><button class="quiet-button full spaced" data-action="tasks">${icon('checklist')} Open honey-do list</button></div><div class="inspector-section"><div class="helper-card">${icon('people')}<strong>Same-device windows sync.</strong>Pop this board out to try two-window editing. Shawn, Gina and Daniel are assignment labels here—not signed-in accounts.</div><p class="compact-info">Online collaboration and authenticated share links are reserved for the production phase. No Cloudflare requests are made.</p></div>`;return;}
 const parents=state.board.objects.filter(x=>x.type==='frame'&&M.canParent(state.board,n.id,x.id));
