 if(e.button!==0)return;
 if(state.tool==='connector'){const endpoint=id?{nodeId:id}:{x:p.x,y:p.y};if(!state.connector){state.connector={start:endpoint,preview:p};$('#tool-hint').textContent='Now click a target object or a free point.';}else if(endpoint.nodeId&&endpoint.nodeId===state.connector.start.nodeId){toast('Choose a different object or a free point.');}else{const start=state.connector.start;mutate('Add connection',b=>b.edges.push({id:M.id(),from:start,to:endpoint,label:'',color:'#b098c7',style:'curve',arrow:true}));setTool('select');}return;}
